/usr/bin/bash -lc "mkdir -p /workspace/run_trace/filtered_counts
perl -Mstrict -Mwarnings -e '
my @files = (
  [\"/workspace/data/inputs/counts_from_reference_condition/srr5085167_counts_table/srr5085167_counts_table.dat\", \"SRR5085167\", \"reference\"],
  [\"/workspace/data/inputs/counts_from_reference_condition/srr5085168_counts_table/srr5085168_counts_table.dat\", \"SRR5085168\", \"reference\"],
  [\"/workspace/data/inputs/counts_from_changed_condition/srr5085169_counts_table/srr5085169_counts_table.dat\", \"SRR5085169\", \"changed\"],
  [\"/workspace/data/inputs/counts_from_changed_condition/srr5085170_counts_table/srr5085170_counts_table.dat\", \"SRR5085170\", \"changed\"],
);
my (@genes, %counts);
for my "'$i (0..$#files) {
  my ($path, $sample) = @{$files[$i]};
  open my $fh, "<", $path or die "open $path: $!";
  my $header = <$fh>; chomp $header;
  my @h = split /'"\\t/, "'$header;
  die "unexpected header in $path: $header'"\\n\" unless @h == 2 && "'$h[0] eq "Geneid" && $h[1] eq $sample;
  my $line_no = 1;
  while (my $line = <$fh>) {
    $line_no++;
    chomp $line;
    my ($gene, $count) = split /'"\\t/, "'$line;
    die "bad row $path:$line_no'"\\n\" unless defined "'$gene && defined $count && $count =~ /''^'"\\d+"'$/;
    if ($i == 0) { push @genes, $gene; }
    else { die "gene order mismatch at $path:$line_no'"\\n\" unless defined "'$genes[$line_no-2] && $genes[$line_no-2] eq $gene; }
    $counts{$sample}{$gene} = $count;
  }
  close $fh;
}
my @retained = grep {
  my $g = $_;
  my $n = 0;
  for my $f (@files) { my $s = $f->[1]; $n++ if $counts{$s}{$g} >= 10; }
  $n >= 2;
} @genes;
for my $f (@files) {
  my ($path, $sample) = @$f;
  my $out = "/workspace/run_trace/filtered_counts/${sample}.filtered.tsv";
  open my $oh, ">", $out or die "write $out: $!";
  print {$oh} "Geneid'"\\t"'$sample'"\\n\";
  for my "'$g (@retained) { print {$oh} "$g'"\\t"'$counts{$sample}{$g}'"\\n\"; }
  close "'$oh;
}
open my $mh, ">", "/workspace/run_trace/filtered_counts/merged_retained_counts.tsv" or die $!;
print {$mh} join("'"\\t\", \"gene_id\", map { "'$_->[1] } @files), "'"\\n\";
for my "'$g (@retained) { print {$mh} join("'"\\t\", "'$g, map { $counts{$_->[1]}{$g} } @files), "'"\\n\"; }
close "'$mh;
open my $lh, ">>", "/workspace/run_trace/execution.log" or die $!;
printf {$lh} "Applied retained-gene filter locally before Galaxy testing: >=10 raw counts in at least two of four samples. Retained %d of %d genes.'"\\n\", scalar(@retained), scalar(@genes);
close "'$lh;
print scalar(@retained), " retained genes'"\\n\";
'"

