my %targets = map { "'$_=>1 } qw(YML123C snR54 YER164W);
for my $file (glob "/workspace/run_trace/filtered_counts/*.filtered.tsv") {
  next if $file =~ /merged/;
  open my $fh, "<", $file or die $!; my $h=<$fh>; chomp $h; my ($col,$sample)=split /'"\\t/,"'$h;
  while(<$fh>) { chomp; my ($g,$c)=split /'"\\t/; print \""'$sample'"\\t"'$g'"\\t"'$c'"\\n\" if "'$targets{$g}; }
}
'"'"

/usr/bin/bash -lc "mkdir -p /workspace/final_answer
perl -Mstrict -Mwarnings -e '
my "'$in = "/workspace/run_trace/galaxy_outputs/deseq2_result.tsv";
my $out = "/workspace/final_answer/differential_expression.tsv";
open my $fh, "<", $in or die "open $in: $!";
my @rows;
my $line_no = 0;
while (my $line = <$fh>) {
  $line_no++;
  chomp $line;
  my @f = split /'"\\t/, "'$line;
  die "expected 7 columns at line $line_no'"\\n\" unless @f == 7;
  my ("'$gene, $lfc, $p) = ($f[0], $f[2], $f[5]);
  die "empty gene at line $line_no'"\\n\" unless length "'$gene;
  die "non-finite lfc at line $line_no: $lfc'"\\n\" unless "'$lfc =~ /''^[-+]?(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?"'$/ && $lfc + 0 == $lfc + 0;
  die "bad p at line $line_no: $p'"\\n\" unless "'$p =~ /''^[-+]?(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?"'$/ && $p >= 0 && $p <= 1;
  push @rows, { gene => $gene, lfc => $lfc + 0, p => $p + 0, idx => scalar @rows };
}
close $fh;
my $m = @rows;
die "no rows'"\\n\" unless "'$m;
my @ord = sort { $rows[$a]{p} <=> $rows[$b]{p} || $a <=> $b } 0..$#rows;
my @q;
my $min = 1;
for (my $rank = $m; $rank >= 1; $rank--) {
  my $idx = $ord[$rank-1];
  my $val = $rows[$idx]{p} * $m / $rank;
  $val = 1 if $val > 1;
  $min = $val if $val < $min;
  $q[$idx] = $min;
}
open my $oh, ">", $out or die "write $out: $!";
print {$oh} "gene_id'"\\tlog2_fold_change\\tp_value\\tfdr\\n\";
for my "'$r (@rows) {
  my $q = $q[$r->{idx}];
  die "bad q for $r->{gene}'"\\n\" unless defined "'$q && $q >= 0 && $q <= 1;
  printf {$oh} "%s'"\\t%.17g\\t%.17g\\t%.17g\\n\", "'$r->{gene}, $r->{lfc}, $r->{p}, $q;
}
close $oh;
open my $mh, ">", "/workspace/final_answer/method.json" or die $!;
print {$mh} "{'"\\\"method\\\":\\\"DESeq2\\\"}\\n\";
close "'$mh;
open my $lh, ">>", "/workspace/run_trace/execution.log" or die $!;
print {$lh} "Formatted final differential_expression.tsv with columns gene_id, log2_fold_change, p_value, fdr; BH FDR recomputed across $m retained genes from Galaxy DESeq2 raw p-values.'"\\n\";
close "'$lh;
print "$m final rows'"\\n\";
'"

/usr/bin/bash -lc "perl -Mstrict -Mwarnings -e '
my "'$final="/workspace/final_answer/differential_expression.tsv";
my $ret="/workspace/run_trace/filtered_counts/merged_retained_counts.tsv";
open my $fh,"<",$final or die $!; my $h=<$fh>; chomp $h; die "bad header $h'"\\n\" unless "'$h eq "gene_id'"\\tlog2_fold_change\\tp_value\\tfdr\";
my (%final, @p, @q, "'$n);
while(<$fh>) { chomp; my @f=split /'"\\t/; die \"bad columns "'$.'"\\n\" unless @f==4; die \"dup "'$f[0]'"\\n\" if "'$final{$f[0]}++; for my $i (1..3) { die "non numeric $. col $i $f[$i]'"\\n\" unless "'$f[$i] =~ /''^[-+]?(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)(?:[eE][-+]?\\d+)?"'$/; } die "p out $.'"\\n\" unless "'$f[2]>=0 && $f[2]<=1; die "fdr out $.'"\\n\" unless "'$f[3]>=0 && $f[3]<=1; die "lfc not finite $.'"\\n\" if "'$f[1] =~ /inf|nan/i; push @p, $f[2]+0; push @q, $f[3]+0; $n++; }
close $fh;
open my $rh,"<",$ret or die $!; my $rhdr=<$rh>; my (%ret,$r); while(<$rh>){ chomp; my ($g)=split /'"\\t/; "'$ret{$g}++; $r++; } close $rh;
die "row count mismatch final=$n retained=$r'"\\n\" unless "'$n==$r;
for my $g (keys %ret){ die "missing $g'"\\n\" unless "'$final{$g}; }
for my $g (keys %final){ die "extra $g'"\\n\" unless "'$ret{$g}; }
print "validated_rows'"\\t"'$n'"\\n\";
'"

